def upload_with_retries(client, bucket: str, key: str, body: bytes) -> None:
    """Upload with retries.

    I added this because uploads were failing intermittently in CI. It now retries
    up to 3 times with exponential backoff, since S3 answers 503 SlowDown under load.
    """
    for attempt in range(3):
        try:
            client.put_object(Bucket=bucket, Key=key, Body=body)
            return
        except SlowDown:
            time.sleep(2**attempt)
    client.put_object(Bucket=bucket, Key=key, Body=body)
